import { Code2, Mail, MessageCircle } from 'lucide-react';
import { profile } from '../data/portfolio';
import { useI18n } from '../i18n';
function InstagramIcon() { return <svg viewBox="0 0 24 24" width="15" height="15" fill="none" stroke="currentColor" strokeWidth="2" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="5" /><circle cx="12" cy="12" r="4" /><circle cx="17.5" cy="6.5" r=".8" fill="currentColor" stroke="none" /></svg>; }
function SocialIcon({ label }: { label: string }) { if (label === 'GitHub') return <Code2 size={15} aria-hidden="true" />; if (label === 'Instagram') return <InstagramIcon />; if (label === 'WhatsApp') return <MessageCircle size={15} aria-hidden="true" />; return <Mail size={15} aria-hidden="true" />; }
export function Footer() { const { t } = useI18n(); return <footer className="site-footer section-wrap"><a className="wordmark footer-wordmark" href="#top" aria-label="H2D.dev"><span>H2D</span><i>.</i><small>dev</small></a><p>{t('footer')}</p><div className="footer-links">{profile.social.map((social) => <a key={social.label} href={social.href} target={social.label === 'Email' ? undefined : '_blank'} rel={social.label === 'Email' ? undefined : 'noreferrer'} aria-label={t(social.label.toLowerCase())}><SocialIcon label={social.label} /><span>{t(social.label.toLowerCase())}</span></a>)}</div><span className="copyright">© {new Date().getFullYear()} {profile.name}</span></footer>; }
